from collections import defaultdict
orbits=defaultdict(list)
for i in range(24):
 for j in range(24):
  key=tuple(sorted({(i,j),(23-i,j),(i,23-j),(23-i,23-j)}))
  orbits[key].append((i,j,g[i][j]))
masked=[(i,j) for i in range(24) for j in range(24) if g[i][j]==2]
no_source=[]
for i,j in masked:
 key=tuple(sorted({(i,j),(23-i,j),(i,23-j),(23-i,23-j)}))
 src=[(r,c,v) for r,c,v in orbits[key] if v!=2]
 if not src: no_source.append((i,j,key))
len(masked),len(no_source),no_source[:5]

